"use client";

import { useParams } from "next/navigation";
import Link from "next/link";
import { ListGroup, ListGroupItem } from "react-bootstrap";
import { BsGripVertical } from "react-icons/bs";
import { useSelector } from "react-redux";
import AssignmentControls from "./AssignmentControls";
import AssignmentControlButtons from "./AssignmentControlButtons";
import AssignmentItemControls from "./AssignmentItemControls";
import { Key, ReactElement, JSXElementConstructor, ReactNode, ReactPortal } from "react";

export default function Assignments() {
  const { cid } = useParams();

  const { assignments } = useSelector((state: any) => state.assignmentsReducer);
  const courses = useSelector((state: any) => state.coursesReducer.courses);
  const course = courses.find((c: any) => c._id === cid);

  const filteredAssignments = course
    ? assignments.filter((a: { course: any; }) => a.course === course._id)
    : [];

  return (
    <div id="wd-assignments">
      <br />
      <AssignmentControls />
      <br /><br /><br />
      <ListGroup className="rounded-0" id="wd-assignments-list">
        <ListGroupItem className="wd-module p-0 mb-5 fs-5 border-gray">
          <div className="wd-title p-3 ps-2 bg-secondary">
            <BsGripVertical className="me-2 fs-3" /> Assignments{" "}
            <AssignmentControlButtons />
          </div>
          <ListGroup className="wd-lessons rounded-0">
            {filteredAssignments.length === 0 && (
              <ListGroupItem className="wd-lesson p-3 ps-1">
                No assignments available for this course.
              </ListGroupItem>
            )}
            {filteredAssignments.map((assignment: { _id: Key | null | undefined; title: string | number | bigint | boolean | ReactElement<unknown, string | JSXElementConstructor<any>> | Iterable<ReactNode> | ReactPortal | Promise<string | number | bigint | boolean | ReactPortal | ReactElement<unknown, string | JSXElementConstructor<any>> | Iterable<ReactNode> | null | undefined> | null | undefined; }) => (
              <ListGroupItem
                key={assignment._id}
                className="wd-lesson p-3 ps-1"
              >
                <BsGripVertical className="me-2 fs-3" />
                <Link
                  href={`/Courses/${cid}/Assignments/${assignment._id}`}
                  className="text-decoration-none text-dark"
                >
                  {assignment.title}
                </Link>
                <AssignmentItemControls/>
              </ListGroupItem>
            ))}
          </ListGroup>
        </ListGroupItem>
      </ListGroup>
    </div>
  );
}
